on conflict (id) do update set
  college_name = excluded.college_name,
  year = excluded.year,
  province = excluded.province,
  program_group = excluded.program_group,
  track = excluded.track,
  first_subject = excluded.first_subject,
  required_subjects = excluded.required_subjects,
  major = excluded.major,
  duration = excluded.duration,
  plan_2025 = excluded.plan_2025,
  plan_2026 = excluded.plan_2026,
  score_2023_highest = excluded.score_2023_highest,
  score_2023_lowest = excluded.score_2023_lowest,
  score_2024_highest = excluded.score_2024_highest,
  score_2024_lowest = excluded.score_2024_lowest,
  score_2025_highest = excluded.score_2025_highest,
  score_2025_lowest = excluded.score_2025_lowest,
  source_title = excluded.source_title,
  source_url = excluded.source_url,
  updated_at = now();
